import os
import sqlite3
import hashlib
import time
from flask import Flask, request, jsonify, session, g
from functools import wraps

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', 'dev-key-change-me')

DATABASE = '/data/app.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY, username TEXT UNIQUE,
        password_hash TEXT, email TEXT, role TEXT DEFAULT 'user',
        api_key TEXT, last_login TEXT, mfa_secret TEXT)''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY, user_id INTEGER, action TEXT,
        details TEXT, timestamp REAL)''')
    db.execute('''CREATE TABLE IF NOT EXISTS documents (
        id INTEGER PRIMARY KEY, owner_id INTEGER, title TEXT,
        content TEXT, classification TEXT DEFAULT 'internal',
        created_at REAL)''')
    db.commit()
    db.close()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if api_key:
            db = get_db()
            user = db.execute('SELECT * FROM users WHERE api_key = ?', (api_key,)).fetchone()
            if user:
                g.current_user = user
                return f(*args, **kwargs)
        if 'user_id' in session:
            db = get_db()
            user = db.execute('SELECT * FROM users WHERE id = ?', (session['user_id'],)).fetchone()
            if user:
                g.current_user = user
                return f(*args, **kwargs)
        return jsonify({'error': 'unauthorized'}), 401
    return decorated

@app.route('/api/documents/search', methods=['GET'])
@require_auth
def search_documents():
    query = request.args.get('q', '')
    classification = request.args.get('classification', 'internal')
    owner_filter = request.args.get('owner', '')

    # Build search query with owner filter
    base_query = "SELECT d.id, d.title, d.classification, d.created_at, u.username as owner FROM documents d JOIN users u ON d.owner_id = u.id WHERE d.classification = '" + classification + "'"

    if owner_filter:
        base_query += " AND u.username = '" + owner_filter + "'"

    if query:
        base_query += " AND d.title LIKE '%" + query + "%'"

    base_query += " ORDER BY d.created_at DESC LIMIT 50"

    try:
        db = get_db()
        results = db.execute(base_query).fetchall()
        return jsonify({'results': [dict(r) for r in results]})
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        return jsonify({'error': 'search failed', 'detail': str(e)}), 500

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
@require_auth
def get_document(doc_id):
    db = get_db()
    doc = db.execute('SELECT * FROM documents WHERE id = ?', (doc_id,)).fetchone()
    if not doc:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(doc))

@app.route('/api/users/profile', methods=['GET'])
@require_auth
def get_profile():
    user = g.current_user
    return jsonify({'id': user['id'], 'username': user['username'],
                    'email': user['email'], 'role': user['role']})

@app.route('/api/audit', methods=['GET'])
@require_auth
def get_audit_log():
    if g.current_user['role'] != 'admin':
        return jsonify({'error': 'forbidden'}), 403
    db = get_db()
    page = request.args.get('page', '1')
    # Intentionally parameterized - not vulnerable
    logs = db.execute('SELECT * FROM audit_log ORDER BY timestamp DESC LIMIT 100 OFFSET ?',
                      (int(page) * 100,)).fetchall()
    return jsonify({'logs': [dict(l) for l in logs]})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'timestamp': time.time()})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
